package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
@Validated
public class RateController {

    /** What the screen shows of a rate; the percent as text with two decimals, and the from-date
     *  (null when it applies from the beginning of time). */
    public record RateView(String grade, String pct, LocalDate from) {
        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getPct().setScale(2).toPlainString(), rate.getFromDate());
        }
    }

    /** The rate form: a percent of 0.00 or more with up to two decimals, and an optional from-date
     *  (left out: from the beginning of time). */
    public record RateForm(@NotNull @Pattern(regexp = "\\s*\\d{1,5}(\\.\\d{1,2})?\\s*") String pct,
            LocalDate from) {

        BigDecimal pctValue() {
            return new BigDecimal(pct.trim()).setScale(2);
        }
    }

    private final RateService service;

    public RateController(RateService service) {
        this.service = service;
    }

    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        return service.list(sheetId.trim()).stream().map(RateView::of).toList();
    }

    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody RateForm form) {
        return RateView.of(service.set(sheetId.trim(), user.trim(), grade, form.pctValue(), form.from()));
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A rate for a grade on a sheet: a percent with two decimals, applying from its from-date (from
 *  the beginning of time when it has none) until a later from-date of the grade takes over. */
@Entity
@Table(name = "rate")
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "pct", nullable = false, precision = 7, scale = 2)
    private BigDecimal pct;

    /** The day the rate applies from; null when it applies from the beginning of time. */
    @Column(name = "from_date")
    private LocalDate fromDate;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, BigDecimal pct, LocalDate fromDate) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.pct = pct;
        this.fromDate = fromDate;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public BigDecimal getPct() {
        return pct;
    }

    public void setPct(BigDecimal pct) {
        this.pct = pct;
    }
}
package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface RateRepository extends JpaRepository<Rate, Long> {

    /** The rates on a sheet, by grade and then from-date, the one with no from-date first. */
    @Query("select r from Rate r where r.sheetId = :sheetId order by r.grade asc, r.fromDate asc nulls first")
    List<Rate> findBySheetIdOrdered(String sheetId);

    Optional<Rate> findBySheetIdAndGradeAndFromDate(String sheetId, String grade, LocalDate fromDate);

    Optional<Rate> findBySheetIdAndGradeAndFromDateIsNull(String sheetId, String grade);

    /** The rates of a grade on a sheet, the latest from-date first and the one with none last. */
    @Query("select r from Rate r where r.sheetId = :sheetId and r.grade = :grade order by r.fromDate desc nulls last")
    List<Rate> findLatestFirst(String sheetId, String grade);

    /** The rate of a grade in force on a day: the one with the latest from-date on or before it, or
     *  else the one with no from-date; empty when the day is before every rate of the grade. */
    default Optional<Rate> findInForce(String sheetId, String grade, LocalDate on) {
        return findLatestFirst(sheetId, grade).stream()
                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(on))
                .findFirst();
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rates for each grade on a sheet, each applying from its from-date. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final Rollup rollup;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, Rollup rollup, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The rates set on the sheet, by grade and then from-date. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrdered(sheetId);
    }

    /** Set the rate for a grade from a date (null: from the beginning of time), replacing the one
     *  the grade had for that from-date. */
    @Transactional
    public synchronized Rate set(String sheetId, String user, String grade, BigDecimal pct, LocalDate from) {
        sheets.load(sheetId, user);
        return rollup.tracking(sheetId, user, () -> {
            Rate rate = (from == null
                    ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
                    : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from))
                    .orElseGet(() -> new Rate(sheetId, grade, pct, from));
            rate.setPct(pct);
            Rate saved = rates.saveAndFlush(rate);
            audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                    + " rate=" + saved.getPct().setScale(2).toPlainString()
                    + (from != null ? " from=" + from : ""));
            return saved;
        });
    }
}
-- The rate for each grade on a sheet: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    pct      DECIMAL(7, 2) NOT NULL CHECK (pct >= 0),
    CONSTRAINT rate_sheet_grade_unique UNIQUE (sheet_id, grade)
